window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d77d829a99cc5cb4"]={"versions": [{"id": "FIG-d77d829a99cc5cb4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class OS-Application Model</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform OS (ab Scalability Class 3 und 4 / SC3/SC4).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Kapselungs- und Partitionierungsdomäne (<code>OS-Application</code>) zur Laufzeit-, Speicher- und Fehlertrennung (Spatial & Temporal Isolation gemäß ISO 26262). Das Modell definiert die Zuweisung von OS-Basisobjekten, Hooks und Schutzmodi zu einer Partition.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kernklasse <code>OS-Application</code>:</strong> Abstrakte Hüll- und Organisationseinheit, die logische Eigentümerin von OS-Ressourcen ist.</li>\n<li><strong>Spezialisierungen (<code>«realize»</code>, <code>{XOR}</code>):</strong></li>\n<li><code>trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {privileged mode}</code>. Besitzt vollen Zugriff auf MPU/Speicher, Peripherie und privilegierte Instruktionen.</li>\n<li><code>non-trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {non-privileged mode}</code>. Unterliegt strikter MPU-Überwachung (Speicherschutz für Stack, Daten, Peripherie).</li>\n<li>*<em>Aggregierte OS-Objekte (Besitzrelation <code>1</code> zu <code></em></code>):**</li>\n<li><code>TASK</code> (<code>#itsTask</code>): Tasks der Partition. Enthält zugeordnete <code>EVENTs</code> (Extended Tasks) sowie maximal einen optionalen <code>Restart-TASK</code> zur Partitions-Wiederherstellung.</li>\n<li><code>ISR</code> (<code>#itsISR</code>): Kategorie-2-Interrupt-Service-Routinen, die der Partition fest zugewiesen sind.</li>\n<li><code>COUNTER</code> (<code>#itsCounter</code>), <code>ALARM</code> (<code>#itsAlarm</code>), <code>SCHEDULETABLE</code> (<code>#itsSchedule</code>): Zeit- und Ablaufsteuerungsobjekte im Eigentum der Applikation.</li>\n<li><strong>Applikationsspezifische Hooks (<code>«Hook»</code>, Besitzrelation <code>1</code> zu <code>0..1</code>):</strong></li>\n<li><code>StartupHook_&lt;Appl&gt;</code> (<code>#itsStartupHook</code>): Initialisierungshook im Kontext der Partition.</li>\n<li><code>ShutdownHook_&lt;Appl&gt;</code> (<code>#itsShutdownHook</code>): Terminierungshook der Partition.</li>\n<li><code>ErrorHook_&lt;Appl&gt;</code> (<code>#itsErrorHook</code>): Lokale Fehlerbehandlung bei OS-Servicefehlern oder Schutzverletzungen innerhalb der Partition.</li>\n<li><strong>Schnittstellen / Bereitgestellte Dienste:</strong></li>\n<li><code>TRUSTED_FUNCTION</code> (<code>+itsProvidedServices</code>): Exklusiv von <code>trusted OS-Application</code> (<code>1</code> zu <code>0..*</code>) bereitgestellte Funktionsaufrufe, die aus <code>non-trusted</code> Domänen synchron angesprungen werden dürfen.</li>\n<li><strong>Objekt-Sharing-Regel (UML-Note):</strong></li>\n<li>Ein OS-Objekt gehört exakt einer <code>OS-Application</code>. Der Zugriff anderer Partitionen (z. B. <code>SetEvent()</code>, <code>SetAbsAlarm()</code>) ist zulässig, sofern in der OS-Konfiguration explizite Zugriffsrechte erteilt wurden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Obgleich es sich um ein Strukturmodell handelt, determinieren die Assoziationen folgende Laufzeitpfade:</p>\n<ul class=\"fig-list\">\n<li><strong>Inter-Partition Service Call (<code>CallTrustedFunction</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Eine <code>non-trusted OS-Application</code> ruft <code>CallTrustedFunction(FunctionIndex, FunctionParams)</code>.</li>\n<li>OS führt MPU-Rekonfiguration, Privilegien-Erhöhung (User Mode $\\rightarrow$ Supervisor Mode) und Stack-Wechsel auf den Stack der Zielapplikation durch.</li>\n<li>Ausführung des synchronen Callbacks <code>TRUSTED_FUNCTION</code>.</li>\n<li>Rücksprung, Stack-Wiederherstellung und Herabstufung in den unprivilegierten Modus.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Cross-Application OS-Access:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>API-Aufruf (z. B. <code>SetEvent(TaskId, Mask)</code>) partitionsextern.</li>\n<li>OS prüft Ownership- und Zugriffsbitmasken der aufrufenden Applikation (<code>CheckObjectAccess()</code>).</li>\n<li>Bei Berechtigung: Ausführung des Dienstes. Bei fehlender Berechtigung: Rückgabe <code>E_OS_ACCESS</code> und Triggerung des Protection-/Error-Handlings.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehler- und Wiederanlaufpfad (Recovery):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Schutzverletzung (MPU-Violation, Task Execution Budget Timeout).</li>\n<li>Aufruf des <code>ProtectionHook</code> $\\rightarrow$ Rückgabe z. B. <code>PRO_TERMINATEAPPL_RESTART</code>.</li>\n<li>OS terminiert alle aktiven Tasks/ISRs der Partition, ruft <code>ShutdownHook_&lt;Appl&gt;</code> auf und aktiviert den designierten <code>One optional restart TASK</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvertrag (ARXML / OIL):</strong> Jedes Task-, ISR-, Counter-, Alarm- und Schedule-Table-Objekt muss zwingend über den Parameter <code>OsApplicationCoreRef</code> / <code>OsApplicationAssignment</code> genau einer Applikation zugeordnet sein.</li>\n<li><strong>Zugriffsmatrizen:</strong> Für jeden partionsübergreifenden Zugriff müssen die Referenzen in <code>OsApplicationAccessingApplication</code> explizit gesetzt werden; andernfalls verweigern OS-APIs zur Laufzeit den Zugriff mit <code>E_OS_ACCESS</code> (oder lösen Schutzreaktionen aus).</li>\n<li><strong>Speicher-Mapping & Linker-Skripte:</strong> Für <code>non-trusted OS-Applications</code> müssen Linker-Sektionen für <code>.bss</code>, <code>.data</code> und Task-Stacks strikt partitioniert und MPU-Alignment-konform ausgerichtet sein (z. B. 32-/64-Byte- oder Potenz-von-2-Grenzen je nach HW-Architektur).</li>\n<li><strong>Design von Trusted Functions:</strong> Da diese im privilegierten Modus laufen, müssen alle übergebenen Pointer gegen Pufferüberläufe und unberechtigte Lese-/Schreibzugriffe auf Fremdspeicher validiert werden (<code>CheckTaskMemoryAccess()</code>), um Privilege-Escalation-Sicherheitslücken zu verhindern.</li>\n</ul>"}, {"id": "FIG-b1ad5e4a53352624", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class OS-Application Model</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform OS (ab Scalability Class 3 und 4 / SC3/SC4).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Kapselungs- und Partitionierungsdomäne (<code>OS-Application</code>) zur Laufzeit-, Speicher- und Fehlertrennung (Spatial & Temporal Isolation gemäß ISO 26262). Das Modell definiert die Zuweisung von OS-Basisobjekten, Hooks und Schutzmodi zu einer Partition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kernklasse <code>OS-Application</code>:</strong> Abstrakte Hüll- und Organisationseinheit, die logische Eigentümerin von OS-Ressourcen ist.</li>\n<li><strong>Spezialisierungen (<code>«realize»</code>, <code>{XOR}</code>):</strong></li>\n<li><code>trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {privileged mode}</code>. Besitzt vollen Zugriff auf MPU/Speicher, Peripherie und privilegierte Instruktionen.</li>\n<li><code>non-trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {non-privileged mode}</code>. Unterliegt strikter MPU-Überwachung (Speicherschutz für Stack, Daten, Peripherie).</li>\n<li>*<em>Aggregierte OS-Objekte (Besitzrelation <code>1</code> zu <code></em></code>):**</li>\n<li><code>TASK</code> (<code>#itsTask</code>): Tasks der Partition. Enthält zugeordnete <code>EVENTs</code> (Extended Tasks) sowie maximal einen optionalen <code>Restart-TASK</code> zur Partitions-Wiederherstellung.</li>\n<li><code>ISR</code> (<code>#itsISR</code>): Kategorie-2-Interrupt-Service-Routinen, die der Partition fest zugewiesen sind.</li>\n<li><code>COUNTER</code> (<code>#itsCounter</code>), <code>ALARM</code> (<code>#itsAlarm</code>), <code>SCHEDULETABLE</code> (<code>#itsSchedule</code>): Zeit- und Ablaufsteuerungsobjekte im Eigentum der Applikation.</li>\n<li><strong>Applikationsspezifische Hooks (<code>«Hook»</code>, Besitzrelation <code>1</code> zu <code>0..1</code>):</strong></li>\n<li><code>StartupHook_&lt;Appl&gt;</code> (<code>#itsStartupHook</code>): Initialisierungshook im Kontext der Partition.</li>\n<li><code>ShutdownHook_&lt;Appl&gt;</code> (<code>#itsShutdownHook</code>): Terminierungshook der Partition.</li>\n<li><code>ErrorHook_&lt;Appl&gt;</code> (<code>#itsErrorHook</code>): Lokale Fehlerbehandlung bei OS-Servicefehlern oder Schutzverletzungen innerhalb der Partition.</li>\n<li><strong>Schnittstellen / Bereitgestellte Dienste:</strong></li>\n<li><code>TRUSTED_FUNCTION</code> (<code>+itsProvidedServices</code>): Exklusiv von <code>trusted OS-Application</code> (<code>1</code> zu <code>0..*</code>) bereitgestellte Funktionsaufrufe, die aus <code>non-trusted</code> Domänen synchron angesprungen werden dürfen.</li>\n<li><strong>Objekt-Sharing-Regel (UML-Note):</strong></li>\n<li>Ein OS-Objekt gehört exakt einer <code>OS-Application</code>. Der Zugriff anderer Partitionen (z. B. <code>SetEvent()</code>, <code>SetAbsAlarm()</code>) ist zulässig, sofern in der OS-Konfiguration explizite Zugriffsrechte erteilt wurden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein Strukturmodell handelt, determinieren die Assoziationen folgende Laufzeitpfade:</p>\n<ul class=\"fig-list\">\n<li><strong>Inter-Partition Service Call (<code>CallTrustedFunction</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Eine <code>non-trusted OS-Application</code> ruft <code>CallTrustedFunction(FunctionIndex, FunctionParams)</code>.</li>\n<li>OS führt MPU-Rekonfiguration, Privilegien-Erhöhung (User Mode $\\rightarrow$ Supervisor Mode) und Stack-Wechsel auf den Stack der Zielapplikation durch.</li>\n<li>Ausführung des synchronen Callbacks <code>TRUSTED_FUNCTION</code>.</li>\n<li>Rücksprung, Stack-Wiederherstellung und Herabstufung in den unprivilegierten Modus.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Cross-Application OS-Access:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>API-Aufruf (z. B. <code>SetEvent(TaskId, Mask)</code>) partitionsextern.</li>\n<li>OS prüft Ownership- und Zugriffsbitmasken der aufrufenden Applikation (<code>CheckObjectAccess()</code>).</li>\n<li>Bei Berechtigung: Ausführung des Dienstes. Bei fehlender Berechtigung: Rückgabe <code>E_OS_ACCESS</code> und Triggerung des Protection-/Error-Handlings.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehler- und Wiederanlaufpfad (Recovery):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Schutzverletzung (MPU-Violation, Task Execution Budget Timeout).</li>\n<li>Aufruf des <code>ProtectionHook</code> $\\rightarrow$ Rückgabe z. B. <code>PRO_TERMINATEAPPL_RESTART</code>.</li>\n<li>OS terminiert alle aktiven Tasks/ISRs der Partition, ruft <code>ShutdownHook_&lt;Appl&gt;</code> auf und aktiviert den designierten <code>One optional restart TASK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvertrag (ARXML / OIL):</strong> Jedes Task-, ISR-, Counter-, Alarm- und Schedule-Table-Objekt muss zwingend über den Parameter <code>OsApplicationCoreRef</code> / <code>OsApplicationAssignment</code> genau einer Applikation zugeordnet sein.</li>\n<li><strong>Zugriffsmatrizen:</strong> Für jeden partionsübergreifenden Zugriff müssen die Referenzen in <code>OsApplicationAccessingApplication</code> explizit gesetzt werden; andernfalls verweigern OS-APIs zur Laufzeit den Zugriff mit <code>E_OS_ACCESS</code> (oder lösen Schutzreaktionen aus).</li>\n<li><strong>Speicher-Mapping & Linker-Skripte:</strong> Für <code>non-trusted OS-Applications</code> müssen Linker-Sektionen für <code>.bss</code>, <code>.data</code> und Task-Stacks strikt partitioniert und MPU-Alignment-konform ausgerichtet sein (z. B. 32-/64-Byte- oder Potenz-von-2-Grenzen je nach HW-Architektur).</li>\n<li><strong>Design von Trusted Functions:</strong> Da diese im privilegierten Modus laufen, müssen alle übergebenen Pointer gegen Pufferüberläufe und unberechtigte Lese-/Schreibzugriffe auf Fremdspeicher validiert werden (<code>CheckTaskMemoryAccess()</code>), um Privilege-Escalation-Sicherheitslücken zu verhindern.</li>\n</ul>"}, {"id": "FIG-3336bafd5f247d60", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class OS-Application Model</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform OS (ab Scalability Class 3 und 4 / SC3/SC4).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Kapselungs- und Partitionierungsdomäne (<code>OS-Application</code>) zur Laufzeit-, Speicher- und Fehlertrennung (Spatial & Temporal Isolation gemäß ISO 26262). Das Modell definiert die Zuweisung von OS-Basisobjekten, Hooks und Schutzmodi zu einer Partition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kernklasse <code>OS-Application</code>:</strong> Abstrakte Hüll- und Organisationseinheit, die logische Eigentümerin von OS-Ressourcen ist.</li>\n<li><strong>Spezialisierungen (<code>«realize»</code>, <code>{XOR}</code>):</strong></li>\n<li><code>trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {privileged mode}</code>. Besitzt vollen Zugriff auf MPU/Speicher, Peripherie und privilegierte Instruktionen.</li>\n<li><code>non-trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {non-privileged mode}</code>. Unterliegt strikter MPU-Überwachung (Speicherschutz für Stack, Daten, Peripherie).</li>\n<li>*<em>Aggregierte OS-Objekte (Besitzrelation <code>1</code> zu <code></em></code>):**</li>\n<li><code>TASK</code> (<code>#itsTask</code>): Tasks der Partition. Enthält zugeordnete <code>EVENTs</code> (Extended Tasks) sowie maximal einen optionalen <code>Restart-TASK</code> zur Partitions-Wiederherstellung.</li>\n<li><code>ISR</code> (<code>#itsISR</code>): Kategorie-2-Interrupt-Service-Routinen, die der Partition fest zugewiesen sind.</li>\n<li><code>COUNTER</code> (<code>#itsCounter</code>), <code>ALARM</code> (<code>#itsAlarm</code>), <code>SCHEDULETABLE</code> (<code>#itsSchedule</code>): Zeit- und Ablaufsteuerungsobjekte im Eigentum der Applikation.</li>\n<li><strong>Applikationsspezifische Hooks (<code>«Hook»</code>, Besitzrelation <code>1</code> zu <code>0..1</code>):</strong></li>\n<li><code>StartupHook_&lt;Appl&gt;</code> (<code>#itsStartupHook</code>): Initialisierungshook im Kontext der Partition.</li>\n<li><code>ShutdownHook_&lt;Appl&gt;</code> (<code>#itsShutdownHook</code>): Terminierungshook der Partition.</li>\n<li><code>ErrorHook_&lt;Appl&gt;</code> (<code>#itsErrorHook</code>): Lokale Fehlerbehandlung bei OS-Servicefehlern oder Schutzverletzungen innerhalb der Partition.</li>\n<li><strong>Schnittstellen / Bereitgestellte Dienste:</strong></li>\n<li><code>TRUSTED_FUNCTION</code> (<code>+itsProvidedServices</code>): Exklusiv von <code>trusted OS-Application</code> (<code>1</code> zu <code>0..*</code>) bereitgestellte Funktionsaufrufe, die aus <code>non-trusted</code> Domänen synchron angesprungen werden dürfen.</li>\n<li><strong>Objekt-Sharing-Regel (UML-Note):</strong></li>\n<li>Ein OS-Objekt gehört exakt einer <code>OS-Application</code>. Der Zugriff anderer Partitionen (z. B. <code>SetEvent()</code>, <code>SetAbsAlarm()</code>) ist zulässig, sofern in der OS-Konfiguration explizite Zugriffsrechte erteilt wurden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein Strukturmodell handelt, determinieren die Assoziationen folgende Laufzeitpfade:</p>\n<ul class=\"fig-list\">\n<li><strong>Inter-Partition Service Call (<code>CallTrustedFunction</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Eine <code>non-trusted OS-Application</code> ruft <code>CallTrustedFunction(FunctionIndex, FunctionParams)</code>.</li>\n<li>OS führt MPU-Rekonfiguration, Privilegien-Erhöhung (User Mode $\\rightarrow$ Supervisor Mode) und Stack-Wechsel auf den Stack der Zielapplikation durch.</li>\n<li>Ausführung des synchronen Callbacks <code>TRUSTED_FUNCTION</code>.</li>\n<li>Rücksprung, Stack-Wiederherstellung und Herabstufung in den unprivilegierten Modus.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Cross-Application OS-Access:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>API-Aufruf (z. B. <code>SetEvent(TaskId, Mask)</code>) partitionsextern.</li>\n<li>OS prüft Ownership- und Zugriffsbitmasken der aufrufenden Applikation (<code>CheckObjectAccess()</code>).</li>\n<li>Bei Berechtigung: Ausführung des Dienstes. Bei fehlender Berechtigung: Rückgabe <code>E_OS_ACCESS</code> und Triggerung des Protection-/Error-Handlings.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehler- und Wiederanlaufpfad (Recovery):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Schutzverletzung (MPU-Violation, Task Execution Budget Timeout).</li>\n<li>Aufruf des <code>ProtectionHook</code> $\\rightarrow$ Rückgabe z. B. <code>PRO_TERMINATEAPPL_RESTART</code>.</li>\n<li>OS terminiert alle aktiven Tasks/ISRs der Partition, ruft <code>ShutdownHook_&lt;Appl&gt;</code> auf und aktiviert den designierten <code>One optional restart TASK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvertrag (ARXML / OIL):</strong> Jedes Task-, ISR-, Counter-, Alarm- und Schedule-Table-Objekt muss zwingend über den Parameter <code>OsApplicationCoreRef</code> / <code>OsApplicationAssignment</code> genau einer Applikation zugeordnet sein.</li>\n<li><strong>Zugriffsmatrizen:</strong> Für jeden partionsübergreifenden Zugriff müssen die Referenzen in <code>OsApplicationAccessingApplication</code> explizit gesetzt werden; andernfalls verweigern OS-APIs zur Laufzeit den Zugriff mit <code>E_OS_ACCESS</code> (oder lösen Schutzreaktionen aus).</li>\n<li><strong>Speicher-Mapping & Linker-Skripte:</strong> Für <code>non-trusted OS-Applications</code> müssen Linker-Sektionen für <code>.bss</code>, <code>.data</code> und Task-Stacks strikt partitioniert und MPU-Alignment-konform ausgerichtet sein (z. B. 32-/64-Byte- oder Potenz-von-2-Grenzen je nach HW-Architektur).</li>\n<li><strong>Design von Trusted Functions:</strong> Da diese im privilegierten Modus laufen, müssen alle übergebenen Pointer gegen Pufferüberläufe und unberechtigte Lese-/Schreibzugriffe auf Fremdspeicher validiert werden (<code>CheckTaskMemoryAccess()</code>), um Privilege-Escalation-Sicherheitslücken zu verhindern.</li>\n</ul>"}, {"id": "FIG-55014ee7fad907dd", "releases": ["R21-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class OS-Application Model</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform OS (ab Scalability Class 3 und 4 / SC3/SC4).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Kapselungs- und Partitionierungsdomäne (<code>OS-Application</code>) zur Laufzeit-, Speicher- und Fehlertrennung (Spatial & Temporal Isolation gemäß ISO 26262). Das Modell definiert die Zuweisung von OS-Basisobjekten, Hooks und Schutzmodi zu einer Partition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kernklasse <code>OS-Application</code>:</strong> Abstrakte Hüll- und Organisationseinheit, die logische Eigentümerin von OS-Ressourcen ist.</li>\n<li><strong>Spezialisierungen (<code>«realize»</code>, <code>{XOR}</code>):</strong></li>\n<li><code>trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {privileged mode}</code>. Besitzt vollen Zugriff auf MPU/Speicher, Peripherie und privilegierte Instruktionen.</li>\n<li><code>non-trusted OS-Application</code>: Läuft mit Prozessorbeschränkung <code>constraints {non-privileged mode}</code>. Unterliegt strikter MPU-Überwachung (Speicherschutz für Stack, Daten, Peripherie).</li>\n<li>*<em>Aggregierte OS-Objekte (Besitzrelation <code>1</code> zu <code></em></code>):**</li>\n<li><code>TASK</code> (<code>#itsTask</code>): Tasks der Partition. Enthält zugeordnete <code>EVENTs</code> (Extended Tasks) sowie maximal einen optionalen <code>Restart-TASK</code> zur Partitions-Wiederherstellung.</li>\n<li><code>ISR</code> (<code>#itsISR</code>): Kategorie-2-Interrupt-Service-Routinen, die der Partition fest zugewiesen sind.</li>\n<li><code>COUNTER</code> (<code>#itsCounter</code>), <code>ALARM</code> (<code>#itsAlarm</code>), <code>SCHEDULETABLE</code> (<code>#itsSchedule</code>): Zeit- und Ablaufsteuerungsobjekte im Eigentum der Applikation.</li>\n<li><strong>Applikationsspezifische Hooks (<code>«Hook»</code>, Besitzrelation <code>1</code> zu <code>0..1</code>):</strong></li>\n<li><code>StartupHook_&lt;Appl&gt;</code> (<code>#itsStartupHook</code>): Initialisierungshook im Kontext der Partition.</li>\n<li><code>ShutdownHook_&lt;Appl&gt;</code> (<code>#itsShutdownHook</code>): Terminierungshook der Partition.</li>\n<li><code>ErrorHook_&lt;Appl&gt;</code> (<code>#itsErrorHook</code>): Lokale Fehlerbehandlung bei OS-Servicefehlern oder Schutzverletzungen innerhalb der Partition.</li>\n<li><strong>Schnittstellen / Bereitgestellte Dienste:</strong></li>\n<li><code>TRUSTED_FUNCTION</code> (<code>+itsProvidedServices</code>): Exklusiv von <code>trusted OS-Application</code> (<code>1</code> zu <code>0..*</code>) bereitgestellte Funktionsaufrufe, die aus <code>non-trusted</code> Domänen synchron angesprungen werden dürfen.</li>\n<li><strong>Objekt-Sharing-Regel (UML-Note):</strong></li>\n<li>Ein OS-Objekt gehört exakt einer <code>OS-Application</code>. Der Zugriff anderer Partitionen (z. B. <code>SetEvent()</code>, <code>SetAbsAlarm()</code>) ist zulässig, sofern in der OS-Konfiguration explizite Zugriffsrechte erteilt wurden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein Strukturmodell handelt, determinieren die Assoziationen folgende Laufzeitpfade:</p>\n<ul class=\"fig-list\">\n<li><strong>Inter-Partition Service Call (<code>CallTrustedFunction</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Eine <code>non-trusted OS-Application</code> ruft <code>CallTrustedFunction(FunctionIndex, FunctionParams)</code>.</li>\n<li>OS führt MPU-Rekonfiguration, Privilegien-Erhöhung (User Mode $\\rightarrow$ Supervisor Mode) und Stack-Wechsel auf den Stack der Zielapplikation durch.</li>\n<li>Ausführung des synchronen Callbacks <code>TRUSTED_FUNCTION</code>.</li>\n<li>Rücksprung, Stack-Wiederherstellung und Herabstufung in den unprivilegierten Modus.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Cross-Application OS-Access:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>API-Aufruf (z. B. <code>SetEvent(TaskId, Mask)</code>) partitionsextern.</li>\n<li>OS prüft Ownership- und Zugriffsbitmasken der aufrufenden Applikation (<code>CheckObjectAccess()</code>).</li>\n<li>Bei Berechtigung: Ausführung des Dienstes. Bei fehlender Berechtigung: Rückgabe <code>E_OS_ACCESS</code> und Triggerung des Protection-/Error-Handlings.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehler- und Wiederanlaufpfad (Recovery):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Schutzverletzung (MPU-Violation, Task Execution Budget Timeout).</li>\n<li>Aufruf des <code>ProtectionHook</code> $\\rightarrow$ Rückgabe z. B. <code>PRO_TERMINATEAPPL_RESTART</code>.</li>\n<li>OS terminiert alle aktiven Tasks/ISRs der Partition, ruft <code>ShutdownHook_&lt;Appl&gt;</code> auf und aktiviert den designierten <code>One optional restart TASK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvertrag (ARXML / OIL):</strong> Jedes Task-, ISR-, Counter-, Alarm- und Schedule-Table-Objekt muss zwingend über den Parameter <code>OsApplicationCoreRef</code> / <code>OsApplicationAssignment</code> genau einer Applikation zugeordnet sein.</li>\n<li><strong>Zugriffsmatrizen:</strong> Für jeden partionsübergreifenden Zugriff müssen die Referenzen in <code>OsApplicationAccessingApplication</code> explizit gesetzt werden; andernfalls verweigern OS-APIs zur Laufzeit den Zugriff mit <code>E_OS_ACCESS</code> (oder lösen Schutzreaktionen aus).</li>\n<li><strong>Speicher-Mapping & Linker-Skripte:</strong> Für <code>non-trusted OS-Applications</code> müssen Linker-Sektionen für <code>.bss</code>, <code>.data</code> und Task-Stacks strikt partitioniert und MPU-Alignment-konform ausgerichtet sein (z. B. 32-/64-Byte- oder Potenz-von-2-Grenzen je nach HW-Architektur).</li>\n<li><strong>Design von Trusted Functions:</strong> Da diese im privilegierten Modus laufen, müssen alle übergebenen Pointer gegen Pufferüberläufe und unberechtigte Lese-/Schreibzugriffe auf Fremdspeicher validiert werden (<code>CheckTaskMemoryAccess()</code>), um Privilege-Escalation-Sicherheitslücken zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-d77d829a99cc5cb4", "to": "FIG-b1ad5e4a53352624", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b1ad5e4a53352624", "to": "FIG-3336bafd5f247d60", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3336bafd5f247d60", "to": "FIG-55014ee7fad907dd", "fr": "R4.2.2", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
